head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf05000";
scwin.header_cd = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — bndMktactTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_9_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '113'); } }, { id: "c_when_10_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '111'); } }, { id: "c_when_11_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '121'); } }, { id: "c_when_12_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '131'); } }, { id: "c_when_13_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '141'); } }, { id: "c_when_14_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '151'); } }, { id: "c_when_49", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '113'); } }, { id: "c_otherwise_56", fn: function(){ return (!(((dma_pageContext.get("bndMktactTpCd") ?? "") === '113'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("bndMktactTpNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("isurNm") ?? ""))); } },
        { childId: "__rb2", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } },
        { childId: "__rb3", fn: function () { return String(String((dma_pageContext.get("bndMktactTpNm") ?? ""))) + " (비상장채권목록)"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_openNewListingReq').set('pageIndex', "1");
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(>- vs eachlisting vs listeach) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.header_cd =$('input[name=bnd_mktact_tp_cd]').val(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf05000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchList_onclick
 * @description btn_searchList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05000.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeypress
 * @description ipt_searchWord onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onkeypress = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05000.ipt_searchWord_onkeypress' }); }
};

/**
 * @method
 * @name ipt_searchWord_onpaste
 * @description ipt_searchWord onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05000.ipt_searchWord_onpaste' }); }
};

/**
 * @method
 * @name btn_issInstNew_onclick
 * @description btn_issInstNew 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_issInstNew_onclick = function(e){
    try {
        scwin.issInstNew()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05000.btn_issInstNew_onclick' }); }
};

/**
 * @method
 * @name btn_issInstNew_2_onclick
 * @description btn_issInstNew_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_issInstNew_2_onclick = function(e){
    try {
        scwin.issInstNew()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05000.btn_issInstNew_2_onclick' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.openNonListingBond(r["isuCd"], r["bndApplId"], r["bndListProcsTpCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_openNewListing
 * @description open New Listing 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openNewListing = async function () {
    const sbmOptions = {
        id: "tx_fn_openNewListing",
        method: "post",
        action: "/listeach/eachListing.do",
        ref: "dma_openNewListingReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_openNonListingBond
 * @description open Non Listing Bond 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openNonListingBond = async function () {
    const sbmOptions = {
        id: "tx_fn_openNonListingBond",
        method: "post",
        action: "/listeach/eachListing.do",
        ref: "dma_openNonListingBondReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/listeach/listeach.do",
        ref: "dma_searchListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name __on_enter_2_ipt_searchword
 * @description on enter 2 ipt searchword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_2_ipt_searchword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05000.__on_enter_2_ipt_searchWord' }); }
};

/**
 * @method
 * @name openNewListing
 * @description open New Listing 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNewListing = async function () {
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent("dma_openNewListingReq").set("stdCd", "");
    $c.util.getComponent("dma_openNewListingReq").set("bndApplId", "");
    $c.util.getComponent("dma_openNewListingReq").set("bndListProcsTpCd", "");
    $c.util.getComponent('dma_openNewListingReq').set('flag', "NEW");
    $c.util.getComponent('dma_openNewListingReq').set('method', 'eachListingView');
    frm.action = '/listeach/eachListing.do';
    await scwin.tx_fn_openNewListing();
};

/**
 * @method
 * @name openNonListingBond
 * @description open Non Listing Bond 처리
 * @param {*} _std_cd _std_cd
 * @param {*} _bnd_appl_id _bnd_appl_id
 * @param {*} _bnd_list_procs_tp_cd _bnd_list_procs_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNonListingBond = async function (_std_cd, _bnd_appl_id, _bnd_list_procs_tp_cd) {
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent("dma_openNewListingReq").set("stdCd", _std_cd);
    $c.util.getComponent("dma_openNewListingReq").set("bndApplId", _bnd_appl_id);
    $c.util.getComponent("dma_openNewListingReq").set("bndListProcsTpCd", _bnd_list_procs_tp_cd);
    if (_bnd_list_procs_tp_cd === '0') {
        $c.util.getComponent('dma_openNewListingReq').set('flag', "TEMP");
    } else {
        $c.util.getComponent('dma_openNewListingReq').set('flag', "CONV");
    }
    $c.util.getComponent('dma_openNewListingReq').set('method', 'eachListingView');
    frm.action = '/listeach/eachListing.do';
    frm.target = "_self";
    await scwin.tx_fn_openNonListingBond();
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent("dma_openNewListingReq").set("efSrhCd", "Y");
    $c.util.getComponent('dma_openNewListingReq').set('method', "searchNonListingBondList");
    frm.action = '/listeach/listeach.do';
    frm.target = "_self";
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name issInstNew
 * @description iss Inst New 처리
 * @returns {void}
 * @hidden N
 */
scwin.issInstNew = function () {
    let base_url = "";
    let url = "";
    let pop_status;
    base_url = "http://isin.krx.co.kr";
    url = base_url;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    pop_status = $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "발행기관신규등록", scrollbars: true, resizable: true, width: "1000", height: "750", type: "pageFramePopup" }, {});
    return;
};

/**
 * @method
 * @name krxpage_pagenavigator_108_onclick
 * @description krxpage_pagenavigator_108 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_108_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_openNewListingReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_108.page' }); } await scwin.searchList(); };
